// https://www.twitch.tv/sableraph
// "Iterations"

const N_FRAMES = 500;

function setup() {
  createCanvas(400, 600);
  noFill();
  rectMode(CENTER);
}

function draw() {
  background("#fffbe6");
  let palette = ["#abcd5e", "#14976b", "#2b67af", "#62b6de", "#f589a3", "#ef562f", "#fc8405", "#f9d531"];

  let t = TAU*(frameCount%N_FRAMES)/N_FRAMES;

  let wMargin = 80;
  let hMargin = 120;
  let nLines = palette.length;
  let h = (height-2*hMargin)/(nLines-1);
  let s = h/sqrt(2)-8;
  for (let i = 0; i < nLines; i++) {
    let y = hMargin + h*i;

    strokeWeight(1);
    stroke(5, 80);
    makeLine(wMargin, y, width-wMargin, y, s, 200, t);

    // add border squares
    strokeWeight(3);
    stroke(palette[i]);
    makeLine(wMargin, y, wMargin, y, s, 1, t);
    stroke(palette[(i+4)%palette.length]);
    makeLine(width-wMargin, y, width-wMargin, y, s, 1, t);

    t *= -1; // flip the direction of the movement
  }
}

function makeLine(x1, y1, x2, y2, s, n, t) {
  for (let i = 0; i < n; i++) {
    let x = map(i, 0, n, x1, x2);
    var y = map(i, 0, n, y1, y2);
    push();
    translate(x, y);
    rotate(1.5*TAU*loopNoise(x, y, t));
    square(0, 0, s);
    pop();
  }
}

// noise on a cylinder, so it loops!
function loopNoise(x, y, theta) {
  let rad = 1, sc = 1/125, offset = 10; // parameters for the noise
  return noise(
    offset + rad*cos(x*sc+theta),
    offset + rad*sin(x*sc+theta),
    y*sc
  );
}
